    @staticmethod
    def apply_typer_to_arg(arg: str,
                           typer: Union[Tuple[Literal[WhichClassForArg.FILESTD], AccessKind],
                                        Tuple[Literal[WhichClassForArg.ARGSTRING], None]]) \
                           -> Union[ArgStringType, FileNameOrStdDescriptorWithIOInfo]:
